CREATE TABLE `admin_account` (
  `id` int NOT NULL COMMENT '主键ID',
  `username` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '后台账号',
  `password` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '密码哈希',
  `type` int NOT NULL DEFAULT '2' COMMENT '账号类型',
  `lastagent` int NOT NULL DEFAULT '1' COMMENT '上级代理ID',
  `lv` int NOT NULL DEFAULT '0' COMMENT '代理等级',
  `qx` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '0' COMMENT '权限配置',
  `agent_tree` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '[0]' COMMENT '代理层级路径',
  `fencheng` int NOT NULL DEFAULT '0' COMMENT '分成比例',
  `invite` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '邀请码',
  `kefu` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '客服信息',
  `wtime` date DEFAULT NULL COMMENT '最近提现日期',
  `wmoney` double(10,2) NOT NULL DEFAULT '0.00' COMMENT '累计已提现金额',
  `status` int NOT NULL DEFAULT '0' COMMENT '状态',
  `direct_commission` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '直属玩家累计佣金',
  `sub_commission` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '下级代理累计佣金',
  `total_commission` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '累计总佣金',
  `direct_player_amount` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '直属玩家累计流水',
  `can_create_agent` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否可创建下级',
  `pending_withdrawal` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '待审核提现金额',
  `withdrawal_apply_time` datetime DEFAULT NULL COMMENT '提现申请时间'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='管理员账号表';

