--
-- 表的结构 `main_pay_channel`
--

CREATE TABLE `main_pay_channel` (
  `id` int NOT NULL COMMENT '主键ID',
  `channel` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '渠道标识',
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '渠道名称',
  `pay_api` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '支付接口地址',
  `pay_pid` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '商户号',
  `pay_key` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '商户密钥',
  `wxpay` int NOT NULL DEFAULT '0' COMMENT '微信支付开关',
  `alipay` int NOT NULL DEFAULT '0' COMMENT '支付宝开关',
  `status` int NOT NULL DEFAULT '0' COMMENT '状态'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='支付渠道配置表';

--
-- 转存表中的数据 `main_pay_channel`
--

