--
-- 表的结构 `main_pay_item`
--

CREATE TABLE `main_pay_item` (
  `id` int NOT NULL COMMENT '主键ID',
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '商品名称',
  `icon` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '图标资源',
  `price` int NOT NULL COMMENT '价格',
  `daylimit` int NOT NULL COMMENT '每日限购',
  `rolelimit` int NOT NULL DEFAULT '0' COMMENT '角色限购',
  `info` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '商品说明',
  `mailinfo` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '邮件发奖配置',
  `xianyu` int NOT NULL DEFAULT '0' COMMENT '仙玉奖励',
  `vip` int NOT NULL DEFAULT '0' COMMENT 'VIP奖励',
  `effect` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '0' COMMENT '效果配置',
  `status` int NOT NULL DEFAULT '0' COMMENT '状态',
  `beishu` int NOT NULL DEFAULT '0' COMMENT '倍数标记'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='充值商品配置表';

