--
-- 表的结构 `main_server`
--

CREATE TABLE `main_server` (
  `id` int NOT NULL COMMENT '主键ID',
  `groupname` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '分组名称',
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '区服名称',
  `serverip` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '区服IP',
  `serverport` int NOT NULL COMMENT '游戏端口',
  `gmport` int NOT NULL COMMENT 'GM端口',
  `serverid` int NOT NULL COMMENT '区服ID',
