--
-- 表的结构 `user_order`
--

CREATE TABLE `user_order` (
  `id` int NOT NULL COMMENT '主键ID',
  `orderid` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '业务订单号',
  `agent` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '代理快照',
  `ordertype` int NOT NULL DEFAULT '1' COMMENT '订单类型',
  `user` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '用户快照',
  `item` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '商品快照',
  `channel` int NOT NULL COMMENT '支付渠道ID',
  `paytype` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '支付方式',
  `realmoney` decimal(10,2) NOT NULL COMMENT '实付金额',
  `date` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '下单日期',
  `time` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '下单时间戳',
  `ip` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'IP地址',
  `city` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '城市',
  `status` int NOT NULL DEFAULT '0' COMMENT '订单状态'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='用户订单表';

-- --------------------------------------------------------

--
-- 表的结构 `user_transfer`
--

CREATE TABLE `user_transfer` (
  `id` int NOT NULL COMMENT '主键ID',
  `uid` int NOT NULL DEFAULT '0' COMMENT '用户ID',
  `username` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '用户名',
  `role` int NOT NULL DEFAULT '0' COMMENT '源角色ID',
  `source_server_id` int NOT NULL DEFAULT '0' COMMENT '源区服ID',
  `target_server_id` int NOT NULL DEFAULT '0' COMMENT '目标区服ID',
  `target_role_id` int NOT NULL DEFAULT '0' COMMENT '目标角色ID',
  `target_role_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '目标角色名',
  `contact` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '联系方式',
  `reason` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '转区原因',
  `type` int NOT NULL DEFAULT '2' COMMENT '申请类型',
  `reply` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '审核回复',
  `admin_id` int DEFAULT NULL COMMENT '处理管理员ID',
  `status` int NOT NULL DEFAULT '0' COMMENT '审核状态',
  `processed_at` datetime DEFAULT NULL COMMENT '处理时间',
  `created_at` datetime DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime DEFAULT NULL COMMENT '更新时间'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='转区申请表';

-- --------------------------------------------------------

--
-- 表的结构 `user_voice`
--

CREATE TABLE `user_voice` (
  `id` int NOT NULL COMMENT '主键ID',
  `uuid` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '语音唯一标识',
  `text` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '语音文本',
  `channelid` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '频道ID',
  `time` int NOT NULL COMMENT '语音时长'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='语音记录表';

-- --------------------------------------------------------

--
-- 表的结构 `withdrawal_records`
--

CREATE TABLE `withdrawal_records` (
  `id` int NOT NULL COMMENT '主键ID',
  `agent_id` int NOT NULL COMMENT '代理ID',
  `agent_username` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '代理账号',
  `withdrawal_amount` decimal(10,2) NOT NULL COMMENT '提现金额',
  `direct_commission` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '直属佣金',
  `sub_commission` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '下级佣金',
  `payment_method` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '收款方式',
  `zfb_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '收款姓名',
  `zfb_account` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '收款账号',
  `usdt_address` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'USDT地址',
  `apply_time` datetime DEFAULT NULL COMMENT '申请时间',
  `settlement_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '结算时间',
  `settlement_admin` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '结算管理员',
  `settlement_admin_id` int DEFAULT NULL COMMENT '结算管理员ID',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '状态'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='提现结算记录表';

